#
# ======================================================================================
# Creates or updates this PR's SPRT results comment.
# Usage: UpdatePRComment.sh <body file>
# Requires GH_TOKEN, GITHUB_REPOSITORY, and PR_NUMBER to be set.

set -euo pipefail

readonly marker='<!-- benbot-sprt-results -->'

body_file="$(mktemp)"
{ echo "$marker"; cat "$1"; } > "$body_file"

comment_id="$(gh api "repos/$GITHUB_REPOSITORY/issues/$PR_NUMBER/comments" --paginate \
    --jq ".[] | select(.user.login == \"github-actions[bot]\" and (.body | contains(\"$marker\"))) | .id" \
    | head -n 1)"

if [[ -n "$comment_id" ]]; then
    gh api --method PATCH "repos/$GITHUB_REPOSITORY/issues/comments/$comment_id" -F "body=@$body_file" > /dev/null
else
    gh api --method POST "repos/$GITHUB_REPOSITORY/issues/$PR_NUMBER/comments" -F "body=@$body_file" > /dev/null
fi
